    private readonly ActorTimelineOperations _timeline=new();private readonly ActorDefinitionOperations _definitions=new();private readonly PhysicsSettingsOperations _physics=new();private readonly PhysicsInspectorOperations _physicsInspector=new();
    public void refresh(Control owner)
    {
        var model=Ui<RefCounted>(owner,"model");if(owner.Get("_inspecting_file").AsBool()){if(model.Get("selected_id").AsString()==owner.Get("_file_selection").AsString()){owner.Call("_run_inspector_updaters");return;}owner.Set("_inspecting_file",false);}var selected=_timeline.selected_actor(model);string signature=owner.Call("_animated_layout_signature",selected!=null?Variant.From(selected):default).AsString();var previous=owner.Get("_actor").As<Resource>();if(selected==previous&&signature!=owner.Get("_animation_layout_signature").AsString()){owner.Set("_actor",default(Variant));previous=null;}owner.Set("_animation_layout_signature",signature);var fields=Ui<Control>(owner,"fields");if(selected==previous&&fields.GetChildCount()>0){owner.Set("_syncing",true);owner.Call("_run_inspector_updaters");owner.Set("_syncing",false);return;}owner.Set("_actor",selected!=null?Variant.From(selected):default);owner.Set("_restoring_scroll",selected!=null);var updaters=owner.Get("_updaters").AsGodotArray();updaters.Clear();clear_fields(owner);if(selected==null){owner.Set("_restoring_scroll",false);add_label(fields,"Select an actor in the timeline.");return;}var actor=selected;var definition=_definitions.get_definition(Ui<RefCounted>(owner,"registry"),actor.Get("type_id").AsStringName());if(definition==null){owner.Set("_restoring_scroll",false);add_label(fields,"Unknown actor type");return;}var identity=new HBoxContainer();identity.AddThemeConstantOverride("separation",10);Ui<Control>(owner,"identity_fields").AddChild(identity);identity.AddChild(new TextureRect{Texture=definition.Get("icon").As<Texture2D>(),CustomMinimumSize=new Vector2(24,24),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered});var identityText=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};identity.AddChild(identityText);var title=new Label{Text=actor.Get("display_name").AsString(),TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis};title.AddThemeFontSizeOverride("font_size",15);identityText.AddChild(title);var type=new Label{Text=definition.Get("category").AsString()+"  /  "+definition.Get("display_name").AsString(),TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,Modulate=new Color("819db4")};type.AddThemeFontSizeOverride("font_size",12);identityText.AddChild(type);updaters.Add(Callable.From(()=>title.Text=actor.Get("display_name").AsString()));var general=section_page(owner,"General","Actor");add_label(general,"Name");var name=new LineEdit{Name="ActorName",Text=actor.Get("display_name").AsString()};general.AddChild(name);void Rename(){_timeline.rename_actor(model,actor,name.Text);name.Text=actor.Get("display_name").AsString();}name.TextSubmitted+=_=>Rename();name.FocusExited+=Rename;updaters.Add(Callable.From(()=>name.Text=actor.Get("display_name").AsString()));var reset=new Button{Name="ResetName",Text="↺ Reset name",TooltipText="Restore the actor type's original name",Visible=actor.Get("display_name").AsString()!=definition.Get("display_name").AsString()};general.AddChild(reset);reset.Pressed+=()=>_timeline.rename_actor(model,actor,definition.Get("display_name").AsString());updaters.Add(Callable.From(()=>reset.Visible=actor.Get("display_name").AsString()!=definition.Get("display_name").AsString()));if(_physics.compatible(actor))_physicsInspector.build(owner,actor,section_page(owner,"Physics","Actor"));if(actor.Get("type_id").AsString()=="skeleton_rig")owner.Call("_add_skeleton_editor",actor);var advanced=new Dictionary<string,VBoxContainer>();string id=actor.Get("id").AsString();var state=Ui<Resource>(owner,"ui_state");foreach(var value in definition.Get("properties").AsGodotArray()){var property=value.As<Resource>();if(!owner.Call("_property_is_visible",property,actor).AsBool())continue;var options=property.Get("options").AsGodotDictionary();string group=options.GetValueOrDefault("group","Properties").AsString();var container=section_page(owner,group,property_main_tab(property));if(options.GetValueOrDefault("advanced",false).AsBool()){if(!advanced.TryGetValue(group,out var advancedPanel)){var categories=_state.actor_state(state,id).GetValueOrDefault("categories",new Settings()).AsGodotDictionary();if(!categories.ContainsKey("PowderMaterial:Advanced"))_state.set_category_expanded(state,id,"PowderMaterial:Advanced",false);advancedPanel=stateful_category(owner,"Advanced",id,container,"PowderMaterial");advanced[group]=advancedPanel;}container=advancedPanel;}owner.Call("_add_property",property,definition,container);}prepare_buttons(owner);string main=_state.main_tab_for(state,id);if(!_state.actor_state(state,id).ContainsKey("main_tab")&&!owner.Get("_sections").AsGodotDictionary().Values.Any(v=>v.AsGodotDictionary()["main"].AsString()=="Properties"))main="Actor";owner.Set("_main_tab",main);owner.Set("_section",_state.section_for(state,id,main));apply_navigation(owner);
    }
    public Godot.Collections.Array<Settings> shader_uniform_layout(Control owner,Shader shader,VBoxContainer parent,string id,string scope)
    {
        var result=new Godot.Collections.Array<Settings>();var containers=new Dictionary<string,VBoxContainer>{{"",parent}};string group="";foreach(var value in shader.GetShaderUniformList(true)){var info=value.AsGodotDictionary();if((info.GetValueOrDefault("usage",0).AsInt64()&(long)PropertyUsageFlags.Group)!=0){group=info.GetValueOrDefault("name","").AsString();continue;}if(info.GetValueOrDefault("name","").AsString().Length==0)continue;if(!containers.ContainsKey(group)){var parts=group.Split("::");string root=parts[0];if(!containers.ContainsKey(root))containers[root]=stateful_category(owner,root.Capitalize(),id,parent,scope+":"+root);if(parts.Length>1)containers[group]=stateful_category(owner,parts[1].Capitalize(),id,containers[root],scope+":"+group);}result.Add(new Settings{["info"]=info,["parent"]=containers[group]});}return result;
    }
    public Shader? shader_from_value(Variant value){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Shader shader)return shader;string path=value.ToString();return path.Length>0?ResourceLoader.Load<Shader>(path,"",ResourceLoader.CacheMode.Ignore):null;}
    public Variant shader_uniform_default(Shader shader,StringName name,int type){if(type==(int)Variant.Type.Object)return "";var value=RenderingServer.ShaderGetParameterDefault(shader.GetRid(),name);if(value.VariantType!=Variant.Type.Nil)return value;return (Variant.Type)type switch{Variant.Type.Float=>Variant.From(0.0),Variant.Type.Int=>Variant.From(0),Variant.Type.Bool=>Variant.From(false),Variant.Type.Vector2=>Variant.From(Vector2.Zero),Variant.Type.Vector3=>Variant.From(Vector3.Zero),Variant.Type.Vector4=>Variant.From(Vector4.Zero),Variant.Type.Color=>Variant.From(Colors.White),_=>default};}
